import { METADATA_LOOKUP_LIMITS, type MusicBrainzRelease, type MusicBrainzReleaseSummary, type MusicBrainzTrack } from './lookupContract';

/**
 * Pure subset pairing of an existing Album's members with a release's tracks: which release tracks count as audio, the expected
 * tracklist rows a release offers within the Album's bounds, whether exactly one pairing exists, the pairs every maximum pairing
 * shares, the rows each member may take when the administrator pairs the members by hand (lookupPairingOptions, closest first, with
 * the pairs every maximum pairing shares marked), and the track-count helpers that admit and order releases for such a comparison.
 * A pairing that is not single may still resolve to one through the members' position hints or near-exact durations
 * (lookupResolvedPairing), which records how. It never makes a request and imports only the lookup contract, so the ranking
 * (lookupRanking.ts) builds on it without a cycle. Every function is total on stored shapes: a non-array is empty, a non-positive
 * or non-finite duration is unknown (a release track's also when it is not whole milliseconds, as the expected tracklist stores
 * them), and a Disc or Track Number that is not a safe integer of at least 1 is missing.
 */
export type LookupPairingSlot = { discNumber: number; trackNumber: number; durationMs: number | null };
/** How a pairing that was not single became single: by the members' title positions, filename positions or near-exact durations. */
export type LookupPairedBy = 'titlePositions' | 'fileNamePositions' | 'nearExactDuration';
/**
 * An existing-Album review member's leading title (or retained filename) position: a pairing hint only, never an own number. A
 * missing Disc Number matches any disc.
 */
export type LookupPositionHint = { discNumber: number | null; trackNumber: number; from: 'title' | 'fileName' };
/**
 * A member's own numbers and duration; 1000 ms precision marks a legacy `m:ss` duration, as for import files. `positionHint` is
 * present only on a review's members, when every member's title (else filename) position counts (lookupReviewEvidence.ts).
 */
export type LookupPairingMember = { slotId: string; discNumber: number | null; trackNumber: number | null; durationMs: number | null; durationPrecisionMs: 0 | 1000;
    positionHint?: LookupPositionHint };
export type LookupSubsetPair = { slotId: string; discNumber: number; trackNumber: number };
/** `pairedBy` (lookupResolvedPairing only): present when several pairings existed and hints or near-exact durations left one. */
export type LookupSubsetPairing = { kind: 'unique'; pairs: LookupSubsetPair[]; pairedBy?: LookupPairedBy } | { kind: 'ambiguous' } | { kind: 'none' };
export type LookupAudioTrack = LookupPairingSlot & { track: MusicBrainzTrack };
export type LookupExpectedRow = LookupPairingSlot & { title: string };
/**
 * The rows a release offers as an expected tracklist (at least one), or why it offers none (`trackCount`: no audio track), with
 * the tracks left out as video, data or pregap.
 */
export type LookupExpectedTracklist = { rows: LookupExpectedRow[]; leftOutTracks: number }
    | { reason: 'trackCount' | 'tooManyTracks' | 'tracklistInvalid'; audioTrackCount: number; leftOutTracks: number };

/** Medium formats whose tracks are video or data, compared NFC, trimmed and lower-cased; any other format, or none, is audio. */
export const LOOKUP_LEFT_OUT_MEDIUM_FORMATS: ReadonlySet<string> = new Set([
    'dvd', 'dvd-video', 'blu-ray', 'blu-ray-r', 'hd-dvd', 'hd dvd', 'vcd', 'svcd', 'vhs', 'betamax', 'laserdisc', 'vhd', 'ced', 'umd',
    'cd-rom', 'dvd-rom', 'data cd', 'data dvd'
]);
/** The bounds of an Album's expected tracklist: rows, UTF-8 bytes of the serialized rows, title length, Disc and Track Number. */
export const LOOKUP_EXPECTED_TRACKLIST_BOUNDS = Object.freeze({ rows: 100, bytes: 32 * 1024, title: 300, disc: 999, track: 9999 });

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const list = (value: unknown): unknown[] => Array.isArray(value) ? value : [];
const ordinal = (value: unknown): number | null => Number.isSafeInteger(value) && (value as number) >= 1 ? value as number : null;
const positive = (value: unknown): number | null => Number.isSafeInteger(value) && (value as number) > 0 ? value as number : null;
const invisible = /[\p{Cc}\p{Cf}\p{Cs}]/u;
const leftOutFormat = (format: unknown) => typeof format === 'string' && LOOKUP_LEFT_OUT_MEDIUM_FORMATS.has(format.normalize('NFC').trim().toLowerCase());
const positionKey = (row: { discNumber: number; trackNumber: number }) => `${row.discNumber}:${row.trackNumber}`;

/** A known duration: positive and finite; anything else is unknown. */
export const lookupDurationMs = (value: unknown): number | null => typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : null;

/**
 * The tracks on audio media in Disc and Track Number order. Every track of a video or data medium, a track whose position is
 * below 1 or not an integer, and each pregap or data track a medium lists apart from its tracks (`hiddenTracks`) counts in
 * `leftOutTracks`. Discs keep the numbering an applied release gives them (proposalForRelease and lookupTrackAssignment): media
 * are numbered 1..n in medium order among those that have tracks, whatever their format, so a CD after a DVD-Video with a
 * tracklist is Disc 2. `discCount` counts the discs that keep an audio track. A duration that is not a positive safe integer is
 * unknown.
 */
export function releaseAudioTracks(release: Pick<MusicBrainzRelease, 'media'>): { tracks: LookupAudioTrack[]; leftOutTracks: number; discCount: number } {
    const tracks: LookupAudioTrack[] = [];
    let leftOutTracks = 0, discNumber = 0, discCount = 0;
    for (const medium of list(isRecord(release) ? release.media : null)) {
        if (!isRecord(medium)) continue;
        const items = list(medium.tracks);
        leftOutTracks += positive(medium.hiddenTracks) ?? 0;
        if (!items.length) continue;
        discNumber++;
        if (leftOutFormat(medium.format)) { leftOutTracks += items.length; continue; }
        const audio = items.filter((track): track is MusicBrainzTrack => isRecord(track) && ordinal(track.position) !== null);
        leftOutTracks += items.length - audio.length;
        if (!audio.length) continue;
        discCount++;
        for (const track of audio) tracks.push({ discNumber, trackNumber: track.position, durationMs: positive(track.lengthMs), track });
    }
    // A stable sort, so repeated positions keep their medium order.
    tracks.sort((left, right) => left.discNumber - right.discNumber || left.trackNumber - right.trackNumber);
    return { tracks, leftOutTracks, discCount };
}

/**
 * The expected tracklist a release offers: one row per audio track (`rows[i]` from `releaseAudioTracks(release).tracks[i]`), its
 * title NFC and trimmed, as the Album's expected-tracklist storage accepts it. A release without audio tracks is `trackCount`;
 * over 100 audio tracks, or rows over 32 KiB of JSON, is `tooManyTracks`; a repeated position, a Disc Number over 999, a Track
 * Number over 9999, or a title that is no string, is empty after trimming, is over 300 characters or holds a control, invisible
 * formatting or lone surrogate character, is `tracklistInvalid`.
 */
export function expectedTracklistFromRelease(release: Pick<MusicBrainzRelease, 'media'>): LookupExpectedTracklist {
    const { tracks, leftOutTracks } = releaseAudioTracks(release), bounds = LOOKUP_EXPECTED_TRACKLIST_BOUNDS;
    const failed = (reason: 'trackCount' | 'tooManyTracks' | 'tracklistInvalid'): LookupExpectedTracklist => ({ reason, audioTrackCount: tracks.length, leftOutTracks });
    if (!tracks.length) return failed('trackCount');
    if (tracks.length > bounds.rows) return failed('tooManyTracks');
    const rows: LookupExpectedRow[] = [], positions = new Set<string>();
    for (const { discNumber, trackNumber, durationMs, track } of tracks) {
        const title = typeof track.title === 'string' ? track.title.normalize('NFC').trim() : null;
        if (!title || title.length > bounds.title || invisible.test(title) || discNumber > bounds.disc || trackNumber > bounds.track
            || positions.has(positionKey({ discNumber, trackNumber }))) return failed('tracklistInvalid');
        positions.add(positionKey({ discNumber, trackNumber }));
        rows.push({ discNumber, trackNumber, title, durationMs });
    }
    return Buffer.byteLength(JSON.stringify(rows), 'utf8') > bounds.bytes ? failed('tooManyTracks') : { rows, leftOutTracks };
}

/**
 * Per member, the slots it may take, in slot order: its own Disc and Track Number equal the slot's where it has them (a missing
 * one matches any), and the durations agree within the tolerance plus the member's precision where both are known. A slot
 * without a valid Disc or Track Number is no position, so no member takes it.
 */
function compatibleSlots(slots: readonly unknown[], members: readonly unknown[], toleranceMs: number): number[][] {
    const usable = slots.map(slot => isRecord(slot) && ordinal(slot.discNumber) !== null && ordinal(slot.trackNumber) !== null
        ? { discNumber: slot.discNumber as number, trackNumber: slot.trackNumber as number, durationMs: lookupDurationMs(slot.durationMs) } : null);
    return members.map(member => {
        if (!isRecord(member)) return [];
        const disc = ordinal(member.discNumber), track = ordinal(member.trackNumber), durationMs = lookupDurationMs(member.durationMs);
        const precision = member.durationPrecisionMs === 1000 ? 1000 : 0;
        return usable.flatMap((slot, index) => slot && (disc === null || disc === slot.discNumber) && (track === null || track === slot.trackNumber)
            && (durationMs === null || slot.durationMs === null || Math.abs(durationMs - slot.durationMs) <= toleranceMs + precision) ? [index] : []);
    });
}

/** A maximum matching by Kuhn's augmenting paths, members tried in order and slots in slot order; -1 marks unmatched. Both sides are at most 100. */
function maximumMatching(edges: readonly (readonly number[])[], slotCount: number) {
    const memberSlot = edges.map(() => -1), slotMember: number[] = Array.from({ length: slotCount }, () => -1);
    const augment = (member: number, visited: boolean[]): boolean => {
        for (const slot of edges[member]) {
            if (visited[slot]) continue;
            visited[slot] = true;
            if (slotMember[slot] < 0 || augment(slotMember[slot], visited)) { memberSlot[member] = slot; slotMember[slot] = member; return true; }
        }
        return false;
    };
    edges.forEach((_edges, member) => augment(member, Array.from({ length: slotCount }, () => false)));
    return { memberSlot, slotMember };
}

const pairOf = (member: unknown, slot: unknown): LookupSubsetPair => ({ slotId: (member as LookupPairingMember).slotId,
    discNumber: (slot as LookupPairingSlot).discNumber, trackNumber: (slot as LookupPairingSlot).trackNumber });

/**
 * Whether exactly one pairing gives every member a distinct slot along `edges` (each member's allowed slots, in slot order): a
 * maximum matching that leaves a member out is `none`; otherwise it is the only one when no member is allowed an unused slot and
 * no members can rotate their slots, meaning the digraph "A -> B when A is allowed B's slot" has no cycle; else `ambiguous`.
 * Pairs follow the members' order.
 */
function pairingAlong(edges: readonly (readonly number[])[], slotList: readonly unknown[], memberList: readonly unknown[]): LookupSubsetPairing {
    const { memberSlot, slotMember } = maximumMatching(edges, slotList.length);
    if (memberSlot.some(slot => slot < 0)) return { kind: 'none' };
    if (edges.some(allowed => allowed.some(slot => slotMember[slot] < 0))) return { kind: 'ambiguous' };
    const next = edges.map((allowed, member) => allowed.map(slot => slotMember[slot]).filter(other => other !== member));
    const colour = memberList.map(() => 0);
    const cyclic = (member: number): boolean => {
        colour[member] = 1;
        for (const other of next[member]) if (colour[other] === 1 || (colour[other] === 0 && cyclic(other))) return true;
        colour[member] = 2;
        return false;
    };
    if (memberList.some((_member, index) => colour[index] === 0 && cyclic(index))) return { kind: 'ambiguous' };
    return { kind: 'unique', pairs: memberList.map((member, index) => pairOf(member, slotList[memberSlot[index]])) };
}

/**
 * Whether exactly one pairing gives every member a distinct compatible slot (pairingAlong over compatibleSlots). No members is the
 * one empty pairing; more members than slots is `none`. Callers pass at most 100 slots (the expected-tracklist bound) and 100
 * members. Never sets `pairedBy`: lookupResolvedPairing resolves a pairing this finds ambiguous.
 */
export function lookupSubsetPairing(slots: readonly LookupPairingSlot[], members: readonly LookupPairingMember[],
    toleranceMs: number = METADATA_LOOKUP_LIMITS.durationToleranceMs): LookupSubsetPairing {
    const slotList = list(slots), memberList = list(members);
    if (!memberList.length) return { kind: 'unique', pairs: [] };
    if (memberList.length > slotList.length) return { kind: 'none' };
    return pairingAlong(compatibleSlots(slotList, memberList, toleranceMs), slotList, memberList);
}

/** A stored hint as pairing reads it: a Disc Number of at least 1 or none, a Track Number of at least 1 and a known source. */
const positionHintOf = (value: unknown): LookupPositionHint | null => isRecord(value) && (value.discNumber === null || ordinal(value.discNumber) !== null)
    && ordinal(value.trackNumber) !== null && (value.from === 'title' || value.from === 'fileName')
    ? { discNumber: value.discNumber as number | null, trackNumber: value.trackNumber as number, from: value.from } : null;

/**
 * The pairing a subset comparison rests on: lookupSubsetPairing's, and when that finds more than one, the only pairing left once
 * each member keeps just its compatible slots at its position hint (every member must carry a usable hint, all of one source; a
 * hint without a Disc Number matches any disc), else just its compatible slots whose duration is within `nearExactMs` of its own
 * (inclusive), both known to the millisecond: the member's not a legacy whole-second one, the slot's not a whole number of seconds
 * (a release length entered in seconds). When several pairings agree with the hints, the duration step chooses only among them,
 * so it never contradicts the positions; when none does, the hints do not count and it chooses among all. Either restriction keeps
 * only compatible slots, so the result is still a pairing within the tolerance and own numbers still constrain first; `pairedBy`
 * says which decided. Otherwise the strict result. Invariant under any permutation of slots and members; at most three matchings
 * of at most 100 by 100.
 */
export function lookupResolvedPairing(slots: readonly LookupPairingSlot[], members: readonly LookupPairingMember[],
    toleranceMs: number = METADATA_LOOKUP_LIMITS.durationToleranceMs, nearExactMs: number = METADATA_LOOKUP_LIMITS.nearExactDurationMs): LookupSubsetPairing {
    const strict = lookupSubsetPairing(slots, members, toleranceMs);
    if (strict.kind !== 'ambiguous') return strict;
    const slotList = list(slots), memberList = list(members), edges = compatibleSlots(slotList, memberList, toleranceMs);
    // compatibleSlots lists only slots with a valid position, so their numbers are ordinals.
    const slotAt = (index: number) => slotList[index] as Record<string, unknown>;
    const hints = memberList.map(member => isRecord(member) ? positionHintOf(member.positionHint) : null), source = hints[0]?.from;
    let candidates: readonly (readonly number[])[] = edges;
    if (source && hints.every(hint => hint?.from === source)) {
        const positioned = edges.map((compatible, member) => compatible.filter(slot => {
            const hint = hints[member]!, at = slotAt(slot);
            return (hint.discNumber === null || hint.discNumber === at.discNumber) && hint.trackNumber === at.trackNumber;
        }));
        const byPosition = pairingAlong(positioned, slotList, memberList);
        if (byPosition.kind === 'unique') return { ...byPosition, pairedBy: source === 'title' ? 'titlePositions' : 'fileNamePositions' };
        if (byPosition.kind === 'ambiguous') candidates = positioned;
    }
    const byDuration = pairingAlong(candidates.map((allowed, member) => {
        const raw = memberList[member], own = isRecord(raw) && raw.durationPrecisionMs !== 1000 ? lookupDurationMs(raw.durationMs) : null;
        return own === null ? [] : allowed.filter(slot => {
            const other = lookupDurationMs(slotAt(slot).durationMs);
            return other !== null && other % 1000 !== 0 && Math.abs(own - other) <= nearExactMs;
        });
    }), slotList, memberList);
    return byDuration.kind === 'unique' ? { ...byDuration, pairedBy: 'nearExactDuration' } : strict;
}

/**
 * The pairs every maximum matching contains, in the members' order; members and slots may each be left over. A pair of a maximum
 * matching M is in every maximum matching exactly when M without it has no augmenting path in the graph without it (Berge),
 * checked by one search phase from every unmatched member that shares the visited slots. Empty when either side is.
 */
export function lookupForcedPairs(slots: readonly LookupPairingSlot[], members: readonly LookupPairingMember[],
    toleranceMs: number = METADATA_LOOKUP_LIMITS.durationToleranceMs): LookupSubsetPair[] {
    const slotList = list(slots), memberList = list(members);
    if (!memberList.length || !slotList.length) return [];
    const edges = compatibleSlots(slotList, memberList, toleranceMs);
    const { memberSlot, slotMember } = maximumMatching(edges, slotList.length);
    const augmentable = (removedMember: number, removedSlot: number) => {
        const visited = slotList.map(() => false);
        const reach = (member: number): boolean => {
            for (const slot of edges[member]) {
                if (visited[slot] || (member === removedMember && slot === removedSlot)) continue;
                visited[slot] = true;
                if (slotMember[slot] < 0 || reach(slotMember[slot])) return true;
            }
            return false;
        };
        return memberSlot.some((slot, member) => slot < 0 && reach(member));
    };
    return memberList.flatMap((member, index) => {
        const slot = memberSlot[index];
        if (slot < 0) return [];
        memberSlot[index] = -1; slotMember[slot] = -1;
        const avoidable = augmentable(index, slot);
        memberSlot[index] = slot; slotMember[slot] = index;
        return avoidable ? [] : [pairOf(member, slotList[slot])];
    });
}

/** The slot IDs of the members compatible with no slot, in the members' order. */
export function lookupUnpairableMembers(slots: readonly LookupPairingSlot[], members: readonly LookupPairingMember[],
    toleranceMs: number = METADATA_LOOKUP_LIMITS.durationToleranceMs): string[] {
    const memberList = list(members), edges = compatibleSlots(list(slots), memberList, toleranceMs);
    return memberList.flatMap((member, index) => edges[index].length ? [] : [(member as LookupPairingMember).slotId]);
}

/** A row a member may take when the administrator pairs by hand, and how far its duration is from the member's (null: either unknown). */
export type LookupPairingOption = { discNumber: number; trackNumber: number; deltaMs: number | null };
/** One member's choices: its options, closest first, and the row every maximum pairing gives it, else null. */
export type LookupMemberPairingOptions = { slotId: string; options: LookupPairingOption[]; forced: { discNumber: number; trackNumber: number } | null };
/** The most rows (an expected tracklist's bound) and members (a review's bound) options are computed for. */
export const LOOKUP_PAIRING_OPTION_BOUNDS = Object.freeze({ rows: LOOKUP_EXPECTED_TRACKLIST_BOUNDS.rows, members: 100 });

/**
 * Per member, in the members' order, the slots it can pair with (compatibleSlots: its own numbers, a missing Disc Number matching
 * any, and the duration within the tolerance plus its precision where both are known, so every such slot when its duration is
 * unknown), closest duration first by the absolute difference, then those whose difference is unknown, ties in Disc and Track
 * Number order; and the slot every maximum pairing gives it (lookupForcedPairs), else null. Position hints are not read. Null over
 * 100 slots or 100 members. Invariant under any permutation of the slots; total on stored shapes.
 */
export function lookupPairingOptions(rows: readonly LookupPairingSlot[], members: readonly LookupPairingMember[],
    toleranceMs: number = METADATA_LOOKUP_LIMITS.durationToleranceMs): LookupMemberPairingOptions[] | null {
    const slotList = list(rows), memberList = list(members);
    if (slotList.length > LOOKUP_PAIRING_OPTION_BOUNDS.rows || memberList.length > LOOKUP_PAIRING_OPTION_BOUNDS.members) return null;
    const edges = compatibleSlots(slotList, memberList, toleranceMs), last = Number.MAX_SAFE_INTEGER;
    const forced = new Map(lookupForcedPairs(slotList as LookupPairingSlot[], memberList as LookupPairingMember[], toleranceMs).map(pair => [pair.slotId, pair]));
    return memberList.map((member, index) => {
        const own = isRecord(member) ? lookupDurationMs(member.durationMs) : null, slotId = isRecord(member) && typeof member.slotId === 'string' ? member.slotId : '';
        // compatibleSlots lists only slots with a valid position, so their numbers are ordinals.
        const options = edges[index].map(slot => {
            const at = slotList[slot] as LookupPairingSlot, other = lookupDurationMs(at.durationMs);
            return { discNumber: at.discNumber, trackNumber: at.trackNumber, deltaMs: own === null || other === null ? null : Math.abs(own - other) };
        }).sort((left, right) => (left.deltaMs ?? last) - (right.deltaMs ?? last) || left.discNumber - right.discNumber || left.trackNumber - right.trackNumber);
        const pair = forced.get(slotId);
        return { slotId, options, forced: pair ? { discNumber: pair.discNumber, trackNumber: pair.trackNumber } : null };
    });
}

/**
 * Whether a release with this audio track count, as lookupAudioTrackCount gives it, can still pair every member: an unknown count
 * (null, or anything but a safe integer of at least 0) or one of at least the member count can; a known 0 never can, as a release
 * without audio tracks matches no Album.
 */
export const lookupSubsetTrackCountPlausible = (count: unknown, memberCount: number): boolean => count !== 0 && (positive(count) === null || (count as number) >= memberCount);

/**
 * The admission order of a release for a subset comparison by its audio track count (lookupAudioTrackCount), smallest first under
 * a stable sort: a known count of at least the member count ranks by its extra tracks, an unknown count after every such release,
 * and a count below the member count, or a known 0, last.
 */
export const lookupSurplusRank = (count: unknown, memberCount: number): number => {
    const known = positive(count);
    return count === 0 ? Number.MAX_SAFE_INTEGER : known === null ? Number.MAX_SAFE_INTEGER - 1 : known >= memberCount ? known - memberCount : Number.MAX_SAFE_INTEGER;
};

/**
 * A found release's or candidate's audio track count, or null when unknown: 0 when its release, else its search summary, lists
 * media and every one is a video or data format (it can match nothing); else a release's audio tracks; else, for a summary that
 * lists media, the track counts of its media whose format is not left out; else a positive summary, found or reported total (a
 * recording hit's total may include video tracks, which it cannot tell apart). An audio medium without a known tracklist
 * leaves a count of 0 unknown.
 */
export function lookupAudioTrackCount(item: { release?: Pick<MusicBrainzRelease, 'media'> | null; summary?: Pick<MusicBrainzReleaseSummary, 'media' | 'trackCount'> | null;
    trackCount?: number | null; reportedTrackCount?: number | null }): number | null {
    const onlyLeftOut = (media: unknown[]) => media.length > 0 && media.every(medium => isRecord(medium) && leftOutFormat(medium.format));
    if (isRecord(item.release)) return onlyLeftOut(list(item.release.media)) ? 0 : positive(releaseAudioTracks(item.release).tracks.length);
    const summary = isRecord(item.summary) ? item.summary : null, media = list(summary?.media);
    if (onlyLeftOut(media)) return 0;
    if (media.length) return positive(media.reduce<number>((sum, medium) => sum
        + (isRecord(medium) && !leftOutFormat(medium.format) ? positive(medium.trackCount) ?? 0 : 0), 0));
    return positive(summary?.trackCount) ?? positive(item.trackCount) ?? positive(item.reportedTrackCount);
}
